export async function getLessonContent(topicId: string): Promise<LessonContent> {
  const loader = LAZY_LESSONS[topicId];
  if (!loader) return getLessonContentFallback(topicId);
  try {
    const data = unwrapModule(await loader());
    if (data && Array.isArray(data.topics) && data.topics.length > 0) {
      const topic = data.topics[0];
      let steps = topic.worked_example?.steps;
      if (Array.isArray(steps)) {
        const enSteps: string[] = [];
        const hiSteps: string[] = [];
        const knSteps: string[] = [];
        steps.forEach((s: any) => {
          if (s) {
            enSteps.push(s.en || '');
            hiSteps.push(s.hi || s.en || '');
            knSteps.push(s.kn || s.en || '');
          }
        });
        steps = { en: enSteps, hi: hiSteps, kn: knSteps };
      }
      return {
        ...topic,
        worked_example: topic.worked_example ? {
          ...topic.worked_example,
          steps: steps
        } : undefined,
        diagram: topic.diagram || {
          source: 'https://picsum.photos/seed/' + topicId + '/360/240',
          caption: 'Visual guide for ' + (topic.title?.en || topicId),
          description: topic.concept_explanation?.en || ''
        }
      };
    }
    
    // Check if it is a curated version 2.0 lesson
    if (data && data.version === '2.0') {
      const titleStr = data.chapter_title || topicId;
      const titleObj = typeof titleStr === 'object' ? titleStr : { en: titleStr, hi: titleStr, kn: titleStr };
      
      const learningObjectives = data.learning_objectives || ['Learn basic concepts'];
      const estimatedMinutes = data.estimated_study_time_minutes || 10;
      
      let conceptExplanationText = '';
      if (data.core_concepts && Array.isArray(data.core_concepts)) {
        conceptExplanationText = data.core_concepts.map((c: any) => `• ${c.concept_name}: ${c.detailed_explanation}`).join('\n\n');
      } else if (data.revision_notes) {
        conceptExplanationText = data.revision_notes;
      } else {
        conceptExplanationText = 'Concept explanation for ' + titleStr;
      }
      
      const conceptExplanation = { en: conceptExplanationText, hi: conceptExplanationText, kn: conceptExplanationText };
      
      const introText = data.introduction?.why_important || '';
      const baseStoryTemplate = {
        en: `Welcome {{STUDENT_NAME}}! Let's explore "${titleStr}" at the {{INTEREST_PLACE}}. ${introText}`,
        hi: `Welcome {{STUDENT_NAME}}! Let's explore "${titleStr}" at the {{INTEREST_PLACE}}. ${introText}`,
        kn: `Welcome {{STUDENT_NAME}}! Let's explore "${titleStr}" at the {{INTEREST_PLACE}}. ${introText}`
      };
      
      let workedExample = {
        problem: 'Example Question',
        steps: { en: ['Step 1'], hi: ['Step 1'], kn: ['Step 1'] },
        answer: 'Answer'
      };
      
      if (data.worked_examples && Array.isArray(data.worked_examples) && data.worked_examples.length > 0) {
        const ex = data.worked_examples[0];
        const steps = ex.step_by_step_answer || [];
        workedExample = {
          problem: ex.question || 'Example Question',
          steps: { en: steps, hi: steps, kn: steps },
          answer: steps.length > 0 ? steps[steps.length - 1] : 'Solved'
        };
      }
      
      const keyPointsArray = data.key_takeaways || data.must_remember_facts || ['Stay focused on key details'];
      const keyPoints = { en: keyPointsArray, hi: keyPointsArray, kn: keyPointsArray };
      
      return {
        topic_id: topicId,
        title: titleObj,
        learning_objectives: learningObjectives,
        estimated_minutes: estimatedMinutes,
        base_story_template: baseStoryTemplate,
        concept_explanation: conceptExplanation,
        worked_example: workedExample,
        key_points: keyPoints,
        interest_placeholders: {
          INTEREST_PLACE: {
            default: { en: 'school classroom', hi: 'विद्यालय', kn: 'ಶಾಲೆ' }
          }
        },
        diagram: {
          source: 'https://picsum.photos/seed/' + topicId + '/360/240',
          caption: 'Visual guide for ' + titleStr,
          description: conceptExplanationText
        }
      };
    }
    
    return getLessonContentFallback(topicId);
  } catch (e) {
    console.error('Error loading lazy lesson content for ' + topicId, e);
    return getLessonContentFallback(topicId);
  }
}

export async function getQuizQuestions(topicId: string): Promise<Question[]> {
  const loader = LAZY_QUIZZES[topicId];
  if (!loader) return getQuizQuestionsFallback(topicId);
  try {
    const questions = normalizeQuizQuestions(await loader(), topicId);
    return questions.length > 0 ? questions : getQuizQuestionsFallback(topicId);
  } catch (e) {
    console.error('Error loading lazy quiz questions for ' + topicId, e);
    return getQuizQuestionsFallback(topicId);
  }
}

export async function getFlashcards(topicId: string): Promise<FlashcardItem[]> {
  const loader = LAZY_FLASHCARDS[topicId];
  if (!loader) return getFlashcardsFallback(topicId);
  try {
    const data = await loader();
    if (data && Array.isArray(data.cards)) {
      return data.cards.map((card: any) => {
        const frontText = card.front || '';
        const backText = card.back || '';
        const hookText = card.memory_hook || '';
        
        return {
          id: card.id,
          front: typeof frontText === 'object' ? frontText : { en: frontText, hi: frontText, kn: frontText },
          back: typeof backText === 'object' ? backText : { en: backText, hi: backText, kn: backText },
          memory_hook: typeof hookText === 'object' ? hookText : { en: hookText, hi: hookText, kn: hookText }
        };
      });
    }
    return getFlashcardsFallback(topicId);
  } catch (e) {
    console.error('Error loading lazy flashcards for ' + topicId, e);
    return getFlashcardsFallback(topicId);
  }
}
